dstt_bt_luy_thua_ma_tran.code:
d = list(map(int, open(0).read().split()))
n, k, M = d[:3]
A = [d[3+i*n:3+(i+1)*n] for i in range(n)]


def mul(X, Y):
    return [[sum(X[i][t] * Y[t][j] for t in range(n)) % M for j in range(n)] for i in range(n)]


if k == 0:
    R = A
else:
    R = None
    B = A
    while k:
        if k & 1:
            R = B if R is None else mul(R, B)
        B = mul(B, B)
        k >>= 1
for r in R:
    print(*r)

